fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0; // Return 0 for an empty array
    }

    let mut distinct_count = 1; // Start with the first element as a distinct value
    let mut last_value = nums[0]; // Initialize the last distinct value

    for &num in &nums[1..] { // Iterate from the second element to the end
        if num != last_value { // Check if the current number is different from the last distinct value
            distinct_count += 1; // Increment the distinct count
            last_value = num; // Update the last distinct value
        }
    }

    distinct_count // Return the count of distinct values
}